DROP TABLE IF EXISTS `loot_groups`;
CREATE TABLE `loot_groups` (
  `groupid` int unsigned NOT NULL COMMENT 'group id (disenchant groups: 900000 + id)',
  `build` int unsigned NOT NULL DEFAULT 0 COMMENT 'valid from this client build',
  `itemid` int unsigned NOT NULL DEFAULT 0 COMMENT 'item, 0 for a group link',
  `group_link` int unsigned NOT NULL DEFAULT 0 COMMENT 'nested group, 0 for an item',
  `chance` float NOT NULL DEFAULT 0 COMMENT 'percent; in a group its share, 0 = rest shared',
  `groupindex` tinyint unsigned NOT NULL DEFAULT 0 COMMENT '0 = own roll, else one drop per index',
  `mincount` int unsigned NOT NULL DEFAULT 1 COMMENT 'minimum stack',
  `maxcount` int unsigned NOT NULL DEFAULT 1 COMMENT 'maximum stack, rolls for a group link',
  PRIMARY KEY (`groupid`, `build`, `itemid`, `group_link`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Loot System';

